/* Assessment to action: synthetic adult training cases, reviewable drafts and shared role handoff. */
(()=>{
let cases=[],error='',legacy=false,filter='All',elapsed=0,busy=false,cloud=null,dirty=false;
let drafts;try{drafts=JSON.parse(localStorage.getItem('fn-a2a-v1'))||{}}catch{drafts={}}
let caseId='A2A-01';
const labels={age:'Age (years)',sex:'Sex for reference dosing weight',weight:'Weight (kg)',height:'Height (cm)',weightVerified:'Weight verified',cancer:'Cancer diagnosis',category:'Cancer category',chemo:'Chemotherapy regimen',chemoDay:'Days since chemotherapy',temp:'Temperature (°C)',method:'Temperature method',feverHours:'Fever duration (hours)',anc:'ANC (×10⁹/L)',expectedDecline:'ANC expected below 0.5 within 48h',sbp:'Systolic BP (mmHg)',dbp:'Diastolic BP (mmHg)',hr:'Heart rate (bpm)',rr:'Respiratory rate (/min)',spo2:'Oxygen saturation (%)',newHypoxia:'New hypoxia',confusion:'Acute confusion',burden:'Symptom burden',copd:'COPD',priorFungal:'Prior invasive fungal infection',dehydration:'Dehydration',setting:'Setting at fever onset',prolonged:'Profound neutropenia expected >7 days',mucositis:'Severe mucositis',pneumonia:'Pneumonia suspected',lineInfection:'Line infection suspected',abdomen:'Enterocolitis suspected',majorComorbidity:'Major comorbidity / organ impairment',crcl:'Verified CrCl for dosing (mL/min)',renalState:'Renal trajectory',dialysis:'Renal replacement',dialysisToday:'HD scheduled today',allergy:'Beta-lactam allergy phenotype',allergyDrug:'Culprit drug category',fqProphylaxis:'Fluoroquinolone prophylaxis',oralIntake:'Oral intake reliable',support:'Caregiver / home support',transport:'Rapid transport available',followup:'Daily follow-up available',resistance:'Documented resistant organism history',mrsa:'Documented MRSA concern',priorAntibiotic:'Already receiving systemic antibiotic',persistentDays:'Days of persistent fever',localProtocol:'Local protocol status'};
const groups=[['History & chemotherapy',['age','sex','weight','height','weightVerified','cancer','category','chemo','chemoDay','setting','burden','copd','priorFungal']],['Vitals & FN assessment',['temp','method','feverHours','anc','expectedDecline','sbp','dbp','hr','rr','spo2','newHypoxia','confusion','dehydration']],['Additional risk & infection focus',['prolonged','mucositis','pneumonia','lineInfection','abdomen','majorComorbidity','resistance','mrsa']],['Renal function & allergy',['crcl','renalState','dialysis','dialysisToday','allergy','allergyDrug']],['Medication history & outpatient suitability',['priorAntibiotic','persistentDays','fqProphylaxis','oralIntake','support','transport','followup','localProtocol']]];
const selectedCase=()=>cases.find(c=>c.id===caseId);
function draft(){const c=selectedCase();return drafts[caseId]||(drafts[caseId]={input:structuredClone(c.input),exclusions:[],done:{},revision:1})}
function persist(){try{localStorage.setItem('fn-a2a-v1',JSON.stringify(drafts))}catch{error='Device storage is unavailable. Use the shared workspace or export your synthetic record.'}}
function setDirty(){dirty=true;const b=document.querySelector('#a2a-unsaved');if(b){b.hidden=false;b.textContent='Unsaved edits — apply assessment to update the displayed draft.'}}
function field(k,p){const label=esc(labels[k]),v=p[k];if(FNAction.bools.includes(k))return `<label>${label}<select name="${k}"><option value="" ${v==null?'selected':''}>Unknown</option><option value="true" ${v===true?'selected':''}>Yes</option><option value="false" ${v===false?'selected':''}>No</option></select></label>`;if(FNAction.enums[k])return `<label>${label}<select name="${k}">${FNAction.enums[k].map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;const range=FNAction.ranges[k];return `<label>${label}<input name="${k}" ${range?`type="number" min="${range[0]}" max="${range[1]}" step="any"`:'maxlength="200"'} value="${esc(v??'')}" placeholder="Unknown"></label>`}
function viewHTML(){if(!cases.length)return header('Patient assessment to action','Loading 20 synthetic adult cases…')+(error?`<p role="alert">${esc(error)}</p><button class="btn" onclick="fnA2A.reload()">Retry loading cases</button>`:'');const c=selectedCase(),d=draft(),r=FNAction.calculate(d.input,c,elapsed),changed=JSON.stringify(d.input)!==JSON.stringify(c.input);return header('Patient assessment to action','History → risk explanation → reviewable order set → first-hour handoff.',`<div class="actions"><button class="btn" onclick="fnA2A.legacy()">Workbook assessments</button><button class="btn" onclick="fnA2A.export()">Export case</button></div>`)+`
<div class="a2a-banner"><b>20 fictional adult FN scenarios · Training draft</b><p>Reference doses require local protocol, prescriber and pharmacy review. No orders are transmitted. This case library does not cover every patient or replace bedside assessment.</p></div>
${error?`<div class="notice" role="alert">${esc(error)}</div>`:''}
<section class="panel a2a-library"><div class="sectiontitle"><div><h2>Choose a clinical scenario</h2><p>Stable candidates, prolonged neutropenia, renal impairment, allergy, resistant organisms and urgent instability.</p></div><label class="field">Case filter<select onchange="fnA2A.filter(this.value)">${['All','Stable candidates','High risk','Urgent instability','Incomplete'].map(x=>`<option ${x===filter?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="a2a-cases">${cases.filter(x=>filter==='All'||filter==='Stable candidates'&&x.expectedPathway==='Low risk candidate'||filter==='High risk'&&x.expectedPathway==='High risk'||filter==='Urgent instability'&&x.expectedPathway.includes('instability')||filter==='Incomplete'&&x.expectedPathway.includes('Incomplete')).map(x=>`<button class="a2a-case ${x.id===caseId?'active':''}" onclick="fnA2A.choose('${x.id}')"><small>${x.id}</small><strong>${esc(x.title)}</strong></button>`).join('')}</div></section>
<div class="a2a-heading"><span class="pill">${c.id} · revision ${d.revision}</span><span class="pill ${r.risk.includes('instability')?'red':'amber'}">${esc(r.risk)}</span><span class="pill">MASCC ${r.mascc.score??'Incomplete'} / 26</span></div>
<section class="panel"><h2>${esc(c.title)}</h2><p>${esc(c.history)}</p><p><b>Previous microbiology:</b> ${esc(c.priorMicrobiology)}</p><p class="mini">Narrative history is context. Verify and edit the structured fields below; prose is not silently converted into clinical findings. Current example: ${esc(d.input.chemo)} · chemotherapy day ${d.input.chemoDay??'unknown'}.</p><details class="a2a-editor"><summary>Edit structured assessment · history, vitals, renal function & eligibility</summary><form id="a2a-form"><div id="a2a-unsaved" class="notice" ${dirty?'':'hidden'}>Unsaved edits — apply assessment to update the displayed draft.</div>${groups.map(([title,keys],i)=>`<details ${i<2?'open':''}><summary>${title}</summary><div class="a2a-fields">${keys.map(k=>field(k,d.input)).join('')}</div></details>`).join('')}<div class="actions"><button class="btn primary" type="submit">Apply assessment & regenerate draft</button><button class="btn" type="button" onclick="fnA2A.discard()">Discard unapplied edits</button><button class="btn" type="button" onclick="fnA2A.reset()">Reset fictional case</button></div></form></details></section>
<div class="a2a-results"><section class="panel"><h2>1 · Explain the pathway</h2><p><b>FN criteria:</b> ${esc(r.fn)}</p><p><b>${esc(r.risk)}</b></p>${r.reasons.length?`<ul>${r.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>No recorded high-risk override. MASCC alone does not authorize outpatient care.</p>'}${r.missing.length?`<div class="notice"><b>Clarify now</b><ul>${r.missing.map(x=>`<li>${esc(labels[x]||x)}</li>`).join('')}</ul></div>`:''}<p>${r.outpatient?'Oral outpatient reference is an eligibility candidate only: observed first dose, at least 4h assessment and clinician disposition decision.':'Inpatient / urgent clinician review pathway. Do not use oral outpatient eligibility from MASCC alone.'}</p><details><summary>MASCC calculation and limitations</summary>${r.mascc.parts.map(x=>`<p>${esc(x.name)}: <b>${x.points??'Unknown'}</b></p>`).join('')}<p>Instability and additional clinical risks override a reassuring score. “High risk + urgent instability” is an escalation label, not a separately validated MASCC risk class. Adult cases only.</p></details></section>
<section class="panel"><h2>2 · Additional assessment & actions</h2>${r.alerts.map(x=>`<div class="a2a-alert">${esc(x)}</div>`).join('')||'<p>Review treatment interactions, infection focus and local susceptibility before approval.</p>'}<p>Review venous access, fluid balance and organ support needs at the bedside. Shock/respiratory concerns require immediate escalation to the responsible emergency/critical-care team. No fluid or vasopressor dose is automated.</p><p><b>Status:</b> generated suggestion · review pending</p></section></div>
<section class="panel a2a-section"><h2>3 · Initial antibacterial draft</h2><p>First dose is distinct from maintenance. Starting an infusion within 60 minutes does not mean completing a long infusion within 60 minutes.</p>${r.meds.length?r.meds.map(m=>`<article class="a2a-drug ${m.blocked?'blocked':''}"><div><h3>${esc(m.name)}</h3><span class="pill amber">${m.blocked?'Individualized review required':'Proposed · unsigned'}</span></div><dl><dt>Initial dose reference</dt><dd>${esc(m.first)}</dd><dt>Infusion / route</dt><dd>${esc(m.infusion)}</dd><dt>Subsequent dosing reference</dt><dd>${esc(m.maintenance)}</dd><dt>Reason</dt><dd>${esc(m.why)}</dd></dl><a href="${FNAction.refs[m.source].url}" target="_blank" rel="noopener">${esc(FNAction.refs[m.source].title)}</a></article>`).join(''):'<div class="notice">No new numeric first dose generated. Review the safety gaps or the already active regimen above. Urgent clinician-directed treatment must continue without waiting for this form.</div>'}<p class="mini">Recheck all allergies, interactions, pregnancy status where relevant, recent doses, organ support and local antibiogram. These references do not authorize prescribing. Duration is determined after clinical and microbiology review.</p></section>
<section class="panel a2a-section"><h2>4 · First 60 minutes — proposed order set</h2><p>Checkboxes choose draft items. They do not record that care occurred. Changes invalidate the local review record.</p><div class="a2a-tasks">${r.checks.map(t=>`<label class="a2a-task"><input type="checkbox" ${!t.include?'disabled title="Not suggested for current assessment"':''} ${t.include&&!d.exclusions.includes(t.code)?'checked':''} onchange="fnA2A.task('${t.code}',this.checked)"><span><b>${esc(t.text)}</b><small>${t.due===0?'Now':'By '+t.due+' min'} · ${esc(t.role)} · ${!t.include?'Not suggested for this assessment':d.done[t.code]?'Manually documented in training at '+new Date(d.done[t.code].at).toLocaleString():'Suggested / not documented'}</small></span></label>`).join('')}</div><div class="actions"><button class="btn" onclick="fnA2A.review()">Record local training review</button><button class="btn" onclick="fnA2A.document()">Document a training action</button></div><p>${d.review?'Local training review: '+esc(d.review.note)+' · '+new Date(d.review.at).toLocaleString():'No local review recorded.'} Device-local records are self-attested; use the shared role handoff below for server-enforced review.</p></section>
<section class="panel a2a-section"><div class="sectiontitle"><div><h2>5 · Results as they become available</h2><p>Simulation clock · independent of actual care or dose documentation.</p></div><label class="field">Time after presentation<select id="a2a-time" onchange="fnA2A.time(Number(this.value))">${[[0,'Presentation'],[15,'15 minutes'],[60,'60 minutes'],[240,'4 hours'],[720,'12 hours'],[1440,'24 hours'],[2880,'48 hours'],[4320,'72 hours'],[7200,'Day 5']].map(([v,l])=>`<option value="${v}" ${v===elapsed?'selected':''}>${l}</option>`).join('')}</select></label></div>${changed?'<div class="notice">Edited assessment: laboratory and culture rows remain the original fictional fixture. They are not newly generated patient results. Original teaching answers below apply to the unedited case.</div>':''}<div class="a2a-results"><div><h3>Laboratory results available now</h3><div class="scroll"><table><thead><tr><th>Test</th><th>Result</th><th>Available</th></tr></thead><tbody>${r.labs.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.value??'Not available'} ${esc(x.unit)}${x.note?'<br>'+esc(x.note):''}</td><td>+${x.at} min</td></tr>`).join('')}</tbody></table></div></div><div><h3>Microbiology & imaging</h3><p>Current culture ${r.cultures.length?'updates below':'pending — no organism or AST yet'}. Historical isolates shown above are distinct from current cultures.</p>${r.cultures.map(x=>`<article class="a2a-alert"><b>+${x.at} min · ${esc(x.specimen)}</b><p>${esc(x.result)} ${x.organism?esc(x.organism):''}</p>${Object.keys(x.ast||{}).length?`<p>${Object.entries(x.ast).map(([k,v])=>esc(k)+': <b>'+esc(v)+'</b>').join(' · ')}</p><small>S/R values are fictional reported susceptibility, not a substitute for MIC, breakpoint or mechanism review.</small>`:''}</article>`).join('')}${r.imaging.map(x=>`<p>+${x.at} min · ${esc(x.test||x.name||'Imaging')} · ${esc(x.text||x.result)}</p>`).join('')}</div></div><details><summary>Original-case teaching timeline (not recorded care)</summary>${c.teaching.filter(t=>t.at<=elapsed).map(t=>`<p><b>+${t.at} min</b> · ${esc(t.action)} ${t.type?'('+esc(t.type)+')':''}</p>`).join('')}<p>These fictional events are answer-key examples. They never populate administration timestamps, task completion or quality measures.</p></details></section>
<section class="panel a2a-section"><h2>6 · Shared physician → pharmacy → nursing handoff</h2><p>Save this synthetic assessment to your existing hospital workspace. Reviews and actual synthetic dose documentation use the established server roles and revision checks.</p><div class="actions"><button class="btn" onclick="fnA2A.connect()" ${busy?'disabled':''}>${busy?'Loading…':'Load my shared workspace'}</button>${cloud?`<button class="btn primary" onclick="fnA2A.saveCloud()" ${busy?'disabled':''}>Save assessment to shared visit</button>`:''}<button class="btn" onclick="go('Team workspace')">Open connected demo</button></div>${cloud?`<label class="field">Hospital workspace<select onchange="fnA2A.workspace(this.value)">${cloud.session.workspaces.map(w=>`<option value="${w.id}" ${w.id===teamWorkspaceId?'selected':''}>${esc(w.name)} · ${esc(w.role)}</option>`).join('')}</select></label>${!cloud.visit?`<label class="field">Synthetic triage time for the new shared visit<input id="a2a-triage" type="datetime-local" value="${localInput(new Date().toISOString())}"></label><p class="mini">This entered triage time is used by the shared handoff. The simulation clock does not set an administration time.</p>`:''}<p>Server role: ${esc(cloud.data.membership.role)}. ${cloud.visit?'Loaded visit '+esc(cloud.visit.id.slice(0,8))+' · revision '+cloud.visit.revision+' · '+esc(teamStages[cloud.visit.stage].label):'No shared visit loaded for this case.'}</p><div class="actions">${cloud.data.visits.filter(v=>v.snapshot.a2a?.caseId===caseId).map(v=>`<button class="btn" onclick="fnA2A.loadVisit('${v.id}')">Load ${v.id.slice(0,8)} · v${v.revision}</button>`).join('')}${cloud.visit?'<button class="btn primary" onclick="fnA2A.handoff()">Continue this role handoff</button>':''}</div>`:''}</section>
<section class="panel a2a-section"><details><summary>Evidence, scope & review status</summary><p>Reference check: 4 November 2026 · A2A-1.0. Draft educational rules: institutional clinical validation, local formulary/antibiogram and pharmacy approval remain pending. Adult fictional cancer-associated FN cases only. Paediatrics, pregnancy-specific treatment, obesity dosing, complex organ support and other resistant mechanisms require individualized review.</p>${Object.values(FNAction.refs).map(x=>`<p><a target="_blank" rel="noopener" href="${x.url}">${esc(x.title)}</a></p>`).join('')}<p><a href="https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=826510bd-b611-42d9-a574-ec7ee4151ef5" target="_blank" rel="noopener">Vancomycin product label — infusion rate and duration</a></p></details></section>`}
function renderA2A(){render();}
function invalidate(d){d.revision++;d.review=null;d.done={};persist()}
function formApply(form){try{const raw={...draft().input};for(const [k,v]of new FormData(form)){raw[k]=FNAction.bools.includes(k)?v===''?null:v==='true':FNAction.ranges[k]?v===''?null:Number(v):v}const p=FNAction.cleanInput(raw);if(JSON.stringify(p)!==JSON.stringify(draft().input)){draft().input=p;invalidate(draft());elapsed=0}dirty=false;error='';renderA2A()}catch(e){error=e.message;renderA2A()}}
function guard(){if(dirty){const notice=document.querySelector('#a2a-unsaved');if(notice){notice.hidden=false;notice.textContent='Apply or discard the unsaved assessment edits first.';notice.scrollIntoView({block:'center'})}return false}return true}
function modal(title,body){openDialog(title,body)}
async function connect(){if(!guard())return;busy=true;error='';render();try{const session=await teamRequest('session');if(!session.workspaces.length)throw Error('No hospital workspace available. Open Connected demo to create or join a synthetic hospital.');if(!session.workspaces.some(w=>w.id===teamWorkspaceId))teamWorkspaceId=session.workspaces[0].id;const data=await teamRequest('workspace');cloud={session,data,visit:cloud?.visit&&data.visits.find(v=>v.id===cloud.visit.id)||null};}catch(e){error=e.message}finally{busy=false;render()}}
window.fnA2A={discard(){dirty=false;error='';render()},reload:load,filter(x){if(!guard())return;filter=x;render()},choose(id){if(!guard())return;caseId=id;elapsed=0;if(cloud)cloud.visit=null;error='';render()},legacy(){legacy=true;render()},async workspace(id){teamWorkspaceId=id;if(cloud)cloud.visit=null;await connect()},time(v){if(!guard())return;elapsed=v;render()},reset(){if(!guard())return;modal('Reset fictional case','<p>This replaces device-local edits and training documentation for this case. Any shared server visit remains available separately.</p><button class="btn primary" onclick="fnA2A.confirmReset()">Reset device draft</button><button class="btn" onclick="closeDialog()">Cancel</button>')},confirmReset(){delete drafts[caseId];elapsed=0;dirty=false;persist();closeDialog();render()},export(){if(!guard())return;download('FN_'+caseId+'_assessment_to_action.json',{syntheticOnly:true,case:selectedCase(),draft:draft(),visibleTime:elapsed,result:FNAction.calculate(draft().input,selectedCase(),elapsed),referenceStatus:'Draft; clinical approval pending'})},task(code,on){if(!guard())return;const d=draft();d.exclusions=on?d.exclusions.filter(x=>x!==code):[...new Set([...d.exclusions,code])];invalidate(d);render()},review(){if(!guard())return;modal('Local training review','<p>Self-attested training record. This does not sign an order or replace server role review.</p><form onsubmit="event.preventDefault();fnA2A.reviewSave(this)"><label class="field">Review rationale<input name="note" required maxlength="500"></label><button class="btn primary">Record training review</button></form>')},reviewSave(f){draft().review={note:new FormData(f).get('note'),at:new Date().toISOString(),revision:draft().revision};persist();closeDialog();render()},document(){if(!guard())return;const r=FNAction.calculate(draft().input,selectedCase(),elapsed);modal('Document a training action',`<p>Manual device-local evidence only. Antibiotic administration uses the shared role handoff and an explicit actual dose time.</p><form onsubmit="event.preventDefault();fnA2A.documentSave(this)"><label class="field">Action<select name="code">${r.checks.filter(t=>t.code!=='antibiotic'&&t.include&&!draft().exclusions.includes(t.code)).map(t=>`<option value="${t.code}">${esc(t.text)}</option>`).join('')}</select></label><label class="field">Documentation note<input name="note" required maxlength="500"></label><button class="btn primary">Record manual training action</button></form>`)},documentSave(f){const v=Object.fromEntries(new FormData(f));draft().done[v.code]={note:v.note,at:new Date().toISOString()};persist();closeDialog();render()},connect,async saveCloud(){if(!guard()||!cloud||busy)return;const enteredTriage=document.querySelector('#a2a-triage')?.value;busy=true;error='';try{const d=draft(),p=d.input;const triageAt=enteredTriage?new Date(enteredTriage).toISOString():new Date().toISOString();render();if(cloud.visit){await teamRequest('assessment-action','POST',{id:cloud.visit.id,revision:cloud.visit.revision,operationKey:teamRequestId(),input:p,exclusions:d.exclusions})}else{const response=await teamRequest('visits','POST',{caseCode:'SIM-'+caseId,requestKey:teamRequestId(),syntheticOnly:true,triageAt,measurements:{age:p.age,temperature:p.temp,anc:p.anc,systolic:p.sbp,crcl:p.crcl},actionCaseId:caseId,actionInput:p,actionExclusions:d.exclusions});cloud.visit={id:response.id}}const data=await teamRequest('workspace');cloud={...cloud,data,visit:data.visits.find(v=>v.id===cloud.visit.id)};error='Assessment saved to shared visit. Physician and pharmacy reviews must be completed for this revision.'}catch(e){error=e.message}finally{busy=false;render()}},loadVisit(id){if(!guard())return;const v=cloud.data.visits.find(v=>v.id===id);if(!v?.snapshot.a2a)return;const a=v.snapshot.a2a;caseId=a.caseId;drafts[caseId]={input:structuredClone(a.input),exclusions:a.exclusions||[],done:{},revision:v.revision};cloud.visit=v;elapsed=0;persist();render()},handoff(){if(!guard()||!cloud?.visit)return;const stored=cloud.visit.snapshot.a2a;if(JSON.stringify(stored.input)!==JSON.stringify(draft().input)||JSON.stringify(stored.exclusions||[])!==JSON.stringify(draft().exclusions)){error='Save assessment changes to the shared visit before continuing this handoff.';render();return}teamData=cloud.data;teamSession=cloud.session;teamVisitId=cloud.visit.id;go('Team workspace')}};
fnA2A.openShared=async function(id){await connect();if(cloud?.data.visits.some(v=>v.id===id)){fnA2A.loadVisit(id);legacy=false;go('Patient assessment')}};
fnA2A.planText=function(snapshot){const a=snapshot.a2a,c=cases.find(c=>c.id===a?.caseId);if(!a||!c)return '';const r=FNAction.calculate(a.input,c,0);return ['A2A-1.0 synthetic assessment; clinical approval pending',c.id+' / '+r.risk+' / MASCC '+(r.mascc.score??'incomplete'),...r.meds.map(m=>m.name+': '+m.first+'; '+m.infusion+'; next: '+m.maintenance),...r.checks.filter(t=>t.include&&!(a.exclusions||[]).includes(t.code)).map(t=>'[Proposed] '+t.text),...r.alerts].join('\n').slice(0,4000)};

const beforeRender=render;render=function(){beforeRender();if(view==='Patient assessment'){if(!legacy){$('#app').innerHTML=viewHTML();const f=$('#a2a-form');if(f){f.onsubmit=e=>{e.preventDefault();formApply(f)};f.addEventListener('input',setDirty);f.addEventListener('change',setDirty)}}else $('#app').insertAdjacentHTML('afterbegin','<button class="btn" onclick="fnA2A.show()">← Patient assessment to action · 20 scenarios</button>')}};
fnA2A.show=()=>{legacy=false;render()};
const beforeGo=go;go=function(v){if(!guard())return;if(v==='Patient assessment')legacy=false;beforeGo(v)};
const beforeOpen=openPatient;openPatient=function(pid){legacy=true;selected=patients.find(p=>id(p)===pid);beforeGo('Patient assessment')};
async function load(){try{const response=await fetch('action-cases.json',{cache:'no-store'});if(!response.ok)throw Error('Case library could not be loaded.');cases=await response.json();error='';if(view==='Patient assessment'&&!legacy)render()}catch(e){error=e.message;if(view==='Patient assessment')render()}}load();
})();
